// Read all uploaded files, order by the date in the filename.
// Oldest = first day of the week (prev), newest = last day (curr).
const item = $('On form submission').first();
const bin = item.binary || {};
const files = Object.keys(bin).map((k) => {
  const b = bin[k];
  const name = String(b.fileName || k);
  const m = name.match(/(\d{4})-(\d{2})-(\d{2})/);
  return { binary: b, name, date: m ? `${m[1]}-${m[2]}-${m[3]}` : '' };
});
if (files.length < 2) {
  throw new Error('Upload at least two days of files from the week.');
}
files.sort((a, b) => (a.date || '').localeCompare(b.date || '')); // oldest first
const prev = files[0];                 // first day of the week
const curr = files[files.length - 1];  // last day of the week
return [{
  json: { currName: curr.name, prevName: prev.name, currDate: curr.date, prevDate: prev.date, days: files.length },
  binary: { curr: curr.binary, prev: prev.binary },
}];

// Compare first day vs last day of the week, grouped by owner.
const rows = $input.all().map((i) => i.json);
const groupByOwner = (arr) => {
  const m = new Map();
  for (const r of arr) {
    const owner = String(r['Assignment'] ?? '').trim();
    const ticket = String(r['Overdue Tickets'] ?? '').trim();
    if (!owner || !ticket) continue;
    if (!m.has(owner)) m.set(owner, new Set());
    m.get(owner).add(ticket);
  }
  return m;
};
const end = groupByOwner(rows.filter((r) => r.period === 'curr'));   // last day
const start = groupByOwner(rows.filter((r) => r.period === 'prev')); // first day
const owners = [...new Set([...end.keys(), ...start.keys()])].sort();
const out = [];
for (const owner of owners) {
  const e = end.get(owner) || new Set();
  const s = start.get(owner) || new Set();
  const added = [...e].filter((t) => !s.has(t)).sort();
  const cleared = [...s].filter((t) => !e.has(t)).sort();
  out.push({ json: {
    'Owner': owner,
    'Start of Week': s.size,
    'End of Week': e.size,
    'Change': e.size - s.size,
    'New Overdue': added.join(', '),
    'Cleared': cleared.join(', '),
  }});
}
return out;
